import React, { useState } from 'react';
import './Profil.css';

const Profil = () => {
  const [activeTab, setActiveTab] = useState('Préférences');
  const [isEditing, setIsEditing] = useState(false);
  const [userData, setUserData] = useState({
    fullName: 'Pierre Michel',
    email: 'pierremichel@gmail.com',
    birthDate: '25 Janvier 1990',
    password: '**********',
    address: '6 rue Firmin Oulès',
    postalCode: '81100',
    city: 'Castres',
    country: 'France'
  });

  const [editData, setEditData] = useState({ ...userData });

  const tabs = [
    { id: 'preferences', label: 'Préférences' },
    { id: 'security', label: 'Sécurité' }
  ];

  const handleEdit = () => {
    setEditData({ ...userData });
    setIsEditing(true);
  };

  const handleCancel = () => {
    setIsEditing(false);
  };

  const handleSave = () => {
    setUserData({ ...editData });
    setIsEditing(false);
    console.log('Données sauvegardées:', editData);
    alert('Modifications enregistrées avec succès!');
  };

  const handleInputChange = (field, value) => {
    setEditData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const fields = [
    { label: 'Prénom et Nom', field: 'fullName' },
    { label: 'Email', field: 'email' },
    { label: 'Date de naissance', field: 'birthDate' },
    { label: 'Mot de passe', field: 'password', type: 'password' },
    { label: 'Adresse', field: 'address' },
    { label: 'Code Postal', field: 'postalCode' },
    { label: 'Ville', field: 'city' },
    { label: 'Pays', field: 'country' }
  ];

  return (
    <div className="profil-container">
      <div className={`profil-card ${isEditing ? 'editing' : 'not-editing'}`}>
        {/* Header avec titre et onglets */}
        <div className="profil-header">
          <h1 className="profil-title">Modifier le profil</h1>
          <div className="profil-tabs">
            {tabs.map(tab => (
              <button
                key={tab.id}
                className={`tab-button ${activeTab === tab.label ? 'active' : ''}`}
                onClick={() => setActiveTab(tab.label)}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        {/* Contenu de la carte */}
        <div className="profil-content">
          {/* Section Avatar */}
          <div className="avatar-section">
            <div className="avatar-circle">PM</div>
            <div className="avatar-info">
              <div className="avatar-name">{userData.fullName}</div>
              <div className="avatar-role">Transporteur coordinateur</div>
              <div className="avatar-email">{userData.email}</div>
            </div>
            <button className="change-avatar-btn">Changer la photo</button>
          </div>

          {/* Formulaire */}
          <div className="form-section">
            {fields.map((item, index) => (
              <div key={index} className="form-row">
                <div className="form-label">{item.label}</div>
                <div className="form-value">
                  {item.type === 'password' ? '•'.repeat(10) : userData[item.field]}
                </div>
                <input
                  type={item.type || 'text'}
                  className="form-input"
                  value={editData[item.field]}
                  onChange={(e) => handleInputChange(item.field, e.target.value)}
                  disabled={!isEditing}
                  style={{ width: '300px' }}
                />
                {!isEditing && (
                  <button 
                    className="edit-button"
                    onClick={handleEdit}
                    style={{ visibility: index === 0 ? 'visible' : 'hidden' }}
                  >
                    Modifier
                  </button>
                )}
              </div>
            ))}
            
            {/* Actions */}
            <div className="form-actions">
              {!isEditing ? (
                <button className="save-button" onClick={handleEdit}>
                  Modifier les informations
                </button>
              ) : (
                <>
                  <button className="cancel-button" onClick={handleCancel}>
                    Annuler
                  </button>
                  <button className="save-button" onClick={handleSave}>
                    Enregistrer
                  </button>
                </>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Profil;
